import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Injectable, signal } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import { Router } from '@angular/router';
import { PermissionDto, UserDto } from '../models/user';
import { environment } from '../environments/environments';
export interface LoginUserDto {
  id: number;
  username: string;
  fullName?: string | undefined;
  email?: string;
  phone?: string;
  role: string;
  accessList?: PermissionDto[];
}

export interface TokenResponseDto {
  accessToken: string;
  refreshToken: string;
  user: LoginUserDto;
}

@Injectable({
  providedIn: 'root'
})
export class Authservice {
  private userKey = 'user';
  private tokenKey = 'accessToken';
  private refreshTokenKey = 'refreshToken';

  private isLoggedInSubject = new BehaviorSubject<boolean>(this.hasToken());
  isLoggedIn$ = this.isLoggedInSubject.asObservable();

  private currentUserSubject = signal<UserDto | null>(null);

  constructor(private http: HttpClient, private router: Router) {}

  private hasToken(): boolean {
    return !!localStorage.getItem(this.tokenKey);
  }

  login(credentials: any): Observable<TokenResponseDto> {
    return this.http.post<TokenResponseDto>(
      // 'http://localhost:5038/api/Auth/login',
      `${environment.apiUrl}/auth/login`,
      credentials,
      { headers: new HttpHeaders({ 'Content-Type': 'application/json' }) }
    );
  }

  setSession(accessToken: string, refreshToken: string, user: LoginUserDto): void {
    localStorage.setItem(this.tokenKey, accessToken);
    localStorage.setItem(this.refreshTokenKey, refreshToken);
    localStorage.setItem(this.userKey, JSON.stringify(user));
    this.currentUserSubject.set(user as UserDto);
    this.isLoggedInSubject.next(true);``

  }

  getToken(): string | null {
    const token = localStorage.getItem(this.tokenKey);
    if (!token) this.redirectToLogin();
    return token;
  }

  getUser(): UserDto | null {
    return (
      this.currentUserSubject() ||
      JSON.parse(localStorage.getItem(this.userKey) || 'null')
    );
  }

  logout(): void {
    localStorage.removeItem(this.tokenKey);
    localStorage.removeItem(this.refreshTokenKey);
    localStorage.removeItem(this.userKey);
    this.currentUserSubject.set(null);
    this.isLoggedInSubject.next(false);
    this.router.navigate(['/login'], { replaceUrl: true });
  }

  hasPermission(permission: string): boolean {
    const user = this.getUser();
    if (!user) return false;
    if (user.role === 'Admin') return true; // Admin override
    return user.accessList?.some((p: PermissionDto) => p.label === permission) ?? false;
  }

  getAllUsers() {
    return this.http.get('http://localhost:5038/api/user');
  }

  // Auto-redirect helper
  private redirectToLogin(): void {
    this.logout(); // clears session & redirects
  }
  getCurrentUser() {
    const user = localStorage.getItem(this.userKey);
    return user ? JSON.parse(user) : null;
  }
}

